<script setup lang="ts">
import FormSelect from '../../Components/FormSelect.vue'
import { computed, nextTick, onMounted, shallowRef, useTemplateRef, watch } from 'vue'
import { Head, useForm, usePage } from '@inertiajs/vue3'
import AuthShell from '../../Components/AuthShell.vue'
import FormErrorSummary from '../../Components/FormErrorSummary.vue'
type Step = 'select' | 'create'
type Tenant = { id: number; name: string; slug: string }
type Plan = { name?: string; price?: string }
type ActionConfig = { method?: string; url?: string | null; fields?: string[] }
const props = withDefaults(defineProps<{ step: Step; tenant?: Tenant | null; tenants?: Tenant[]; can_create?: boolean; selection?: ActionConfig | null; form?: ActionConfig | null; plan?: Plan | null }>(), { tenant: null, tenants: () => [], can_create: false, selection: null, form: null, plan: null })
const page = usePage<{ flash?: { status?: string } }>()
const createForm = useForm({ name: '', slug: '', business_name: '', timezone: 'America/Sao_Paulo', currency: '' })
const selectForm = useForm({})
const selectingTenantId = shallowRef<number | null>(null)
const heading = useTemplateRef<HTMLHeadingElement>('stepHeading')
const errorMessage = computed(() => Object.values(createForm.errors)[0] || Object.values(selectForm.errors)[0] || null)
const currentStep = computed(() => props.step === 'select' ? 1 : 2)
function focusStep() { nextTick(() => heading.value?.focus()) }
function createTenant() { if (props.form?.url) createForm.post(props.form.url, { preserveScroll: true }) }
function retryCreate() { createTenant() }
function selectTenant(tenant: Tenant) { const url = props.tenants?.length === 1 && props.selection?.url ? props.selection.url : `/tenant/select/${tenant.id}`; if (selectForm.processing || !url) return; selectingTenantId.value = tenant.id; selectForm.post(url, { preserveScroll: true, onFinish: () => { selectingTenantId.value = null } }) }
function goBack() { window.history.back() }
onMounted(focusStep)
watch(() => props.step, focusStep)
</script>
