  <AuthShell title="Configure sua operação" eyebrow="Configuração inicial" description="Crie uma operação ou selecione uma já ativa para continuar."><Head title="Configurar operação" /><div class="onboarding-stepper mb-4 flex flex-wrap gap-2 text-sm [&_span]:rounded-full [&_span]:border [&_span]:border-td-border [&_span]:px-3 [&_span]:py-1.5" aria-label="Progresso da configuração" role="list"><span :class="{ 'is-current !border-td-primary !bg-td-primary/8 !text-td-primary font-medium': currentStep === 1 }" role="listitem" :aria-current="currentStep === 1 ? 'step' : undefined">1/2 · Seleção</span><span :class="{ 'is-current !border-td-primary !bg-td-primary/8 !text-td-primary font-medium': currentStep === 2 }" role="listitem" :aria-current="currentStep === 2 ? 'step' : undefined">2/2 · Criação</span></div><button class="btn-text onboarding-back inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg px-3 py-2 text-td-primary hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0 mb-4" type="button" @click="goBack">Voltar</button><p v-if="page.props.flash?.status" class="status-message my-5 flex min-w-0 items-start gap-3 rounded-lg border border-td-green/25 bg-td-green/5 p-4 text-sm leading-6 text-td-green-ink [&_svg]:size-5 [&_svg]:shrink-0" role="status" aria-live="polite">{{ page.props.flash.status }}</p><FormErrorSummary v-if="props.step === 'create'" :errors="createForm.errors" /><p v-if="errorMessage" class="error-summary my-5 flex min-w-0 items-start gap-3 rounded-lg border border-td-red/25 bg-td-red/5 p-4 text-sm leading-6 text-td-red [&_svg]:size-5 [&_svg]:shrink-0" role="alert">{{ errorMessage }}</p><section v-if="props.step === 'select'" class="panel stack min-w-0 rounded-lg border border-td-border bg-white p-6 shadow-td-card sm:p-8 [&_h2]:text-lg [&_h2]:font-medium [&_h2]:leading-7 [&_h2]:text-td-ink [&_h3]:font-medium [&_h3]:text-td-ink [&_dd]:break-words grid gap-6" aria-labelledby="tenant-select-title"><div><h2 id="tenant-select-title" ref="stepHeading" tabindex="-1">Selecione uma operação</h2><p class="form-help mt-2 text-sm leading-6 text-td-body">{{ props.tenant?.name ? `Operação atual: ${props.tenant.name}` : 'Escolha uma operação para continuar.' }}</p></div><div v-if="props.tenants?.length" class="stack grid min-w-0 gap-6"><button v-for="tenant in props.tenants" :key="tenant.id" class="record-card text-left min-w-0 rounded-xl border border-gray-200 bg-white p-4 shadow-theme-sm [&_h3]:text-base [&_h3]:font-medium [&_h3]:text-td-ink [&_dl]:mt-4 [&_dl]:grid [&_dl]:grid-cols-2 [&_dl]:gap-4 [&_dt]:text-sm [&_dt]:text-td-body [&_dd]:mt-1 [&_dd]:break-words [&_svg]:inline-block [&_svg]:size-5 [&_svg]:shrink-0 [&_strong]:font-medium [&_strong]:text-td-ink" type="button" :disabled="selectForm.processing" @click="selectTenant(tenant)"><span class="record-card__top flex flex-wrap items-start justify-between gap-3 [&>div]:min-w-0 [&>div>span]:mt-1 [&>div>span]:block [&>div>span]:text-sm"><strong>{{ tenant.name }}</strong><span v-if="selectingTenantId === tenant.id" role="status" aria-live="polite">Selecionando…</span></span><span class="form-help mt-2 text-sm leading-6 text-td-body">{{ tenant.slug }}</span></button></div><p v-else class="form-help mt-2 text-sm leading-6 text-td-body">Nenhuma operação disponível.</p><button v-if="selectForm.errors.tenant && props.tenants.length" class="btn-text inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg px-3 py-2 text-td-primary hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" type="button" @click="selectTenant(props.tenants[0])">Tentar novamente</button></section><form v-else-if="props.step === 'create' && props.can_create && props.form?.url" class="panel stack min-w-0 rounded-lg border border-td-border bg-white p-6 shadow-td-card sm:p-8 [&_h2]:text-lg [&_h2]:font-medium [&_h2]:leading-7 [&_h2]:text-td-ink [&_h3]:font-medium [&_h3]:text-td-ink [&_dd]:break-words grid grid-cols-12 gap-6 [&>*]:col-span-12" @submit.prevent="createTenant"><div><h2 id="tenant-create-title" ref="stepHeading" tabindex="-1">Crie sua primeira operação</h2><p class="form-help mt-2 text-sm leading-6 text-td-body">{{ props.plan?.name || 'Plano disponível' }}<span v-if="props.plan?.price"> · {{ props.plan.price }}</span></p></div><div class="form-grid grid min-w-0 grid-cols-12 gap-x-7 gap-y-6"><div class="field-group field-group--full col-span-12 grid min-w-0 content-start gap-3"><label class="field-label block text-sm font-medium text-gray-700 dark:text-gray-400" for="tenant-name">Nome da operação</label><input id="tenant-name" v-model="createForm.name" class="form-input w-full min-w-0 scroll-mt-28 rounded-lg border border-td-border bg-transparent px-4 py-2.5 text-sm leading-5 text-td-ink outline-none placeholder:text-td-body/70 focus:border-td-primary focus-visible:ring-2 focus-visible:ring-td-primary/15 disabled:cursor-not-allowed disabled:bg-td-soft disabled:text-td-body file:mr-3 file:rounded file:border-0 file:bg-td-soft file:px-3 file:py-1 file:text-sm file:text-td-primary" required maxlength="255" :aria-invalid="Boolean(createForm.errors.name)" placeholder="Ex.: Oficina Central" /><p v-if="createForm.errors.name" class="field-error text-sm leading-5 text-td-red" role="alert">{{ createForm.errors.name }}</p></div><div class="field-group col-span-12 grid min-w-0 content-start gap-3 sm:col-span-6"><label class="field-label block text-sm font-medium text-gray-700 dark:text-gray-400" for="tenant-slug">Identificador</label><input id="tenant-slug" v-model="createForm.slug" class="form-input w-full min-w-0 scroll-mt-28 rounded-lg border border-td-border bg-transparent px-4 py-2.5 text-sm leading-5 text-td-ink outline-none placeholder:text-td-body/70 focus:border-td-primary focus-visible:ring-2 focus-visible:ring-t