 disabled:text-td-body file:mr-3 file:rounded file:border-0 file:bg-td-soft file:px-3 file:py-1 file:text-sm file:text-td-primary" required placeholder="America/Sao_Paulo" /></div><div class="field-group col-span-12 grid min-w-0 content-start gap-3 sm:col-span-6"><label class="field-label block text-sm font-medium text-gray-700 dark:text-gray-400" for="tenant-currency">Moeda</label><FormSelect id="tenant-currency" v-model="createForm.currency" required placeholder="Selecione uma moeda"><option value="BRL">BRL</option></FormSelect></div></div><div class="form-actions mt-6 grid gap-3"><button class="btn-primary inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg border border-td-primary bg-td-primary px-4 py-2.5 text-sm leading-5 text-white hover:bg-td-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" type="submit" :disabled="createForm.processing" :aria-busy="createForm.processing">{{ createForm.processing ? 'Criando…' : 'Criar operação' }}</button><button v-if="createForm.hasErrors" class="btn-text inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg px-3 py-2 text-td-primary hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" type="button" @click="retryCreate">Tentar novamente</button></div></form><section v-else class="panel min-w-0 rounded-lg border border-td-border bg-white p-6 shadow-td-card sm:p-8 [&_h2]:text-lg [&_h2]:font-medium [&_h2]:leading-7 [&_h2]:text-td-ink [&_h3]:font-medium [&_h3]:text-td-ink [&_dd]:break-words" role="status"><h2 ref="stepHeading" tabindex="-1">Configuração indisponível</h2><p class="form-help mt-2 text-sm leading-6 text-td-body">O servidor não forneceu uma ação válida para esta etapa.</p><button class="btn-text inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg px-3 py-2 text-td-primary hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" type="button" @click="goBack">Voltar</button></section></AuthShell>
</template>
